 1	// RUN: %dafny /compile:0 /dprint:"%t.dprint" "%s" > "%t"
 2	// RUN: %diff "%s.expect" "%t"
 3	
 4	method NinetyOne(x: int, ghost proveFunctionalPostcondition: bool) returns (z: int)
 5	  ensures proveFunctionalPostcondition ==> z == if x > 101 then x-10 else 91;
 6	{
 7	  var y1 := x;
 8	  var y2 := 1;
 9	  while (true)
10	    // the following two invariants are needed only to prove the postcondition
11	    invariant proveFunctionalPostcondition ==> 100 < x ==> y1 == x;
12	    invariant proveFunctionalPostcondition ==> x <= 100 < y1 && y2 == 1 ==> y1 == 101;
13	    // the following two lines justify termination, as in the paper by Katz and Manna
14	    invariant (y1 <= 111 && y2 >= 1) || (y1 == x && y2 == 1);
15	    decreases -2*y1 + 21*y2 + 2*(if x < 111 then 111 else x);
16	  {
17	    if (y1 > 100) {
18	      if (y2 == 1) {
19	        break;
20	      } else {
21	        y1 := y1 - 10;
22	        y2 := y2 - 1;
23	      }
24	    } else {
25	      y1 := y1 + 11;
26	      y2 := y2 + 1;
27	    }
28	  }
29	  z := y1 - 10;
30	}
31	
32	method Gcd(x1: int, x2: int)
33	  requires 1 <= x1 && 1 <= x2;
34	{
35	  var y1 := x1;
36	  var y2 := x2;
37	  while (y1 != y2)
38	    invariant 1 <= y1 && 1 <= y2;
39	    decreases y1 + y2;
40	  {
41	    while (y1 > y2)
42	      invariant 1 <= y1 && 1 <= y2;
43	    {
44	      y1 := y1 - y2;
45	    }
46	    while (y2 > y1)
47	      invariant 1 <= y1 && 1 <= y2;
48	    {
49	      y2 := y2 - y1;
50	    }
51	  }
52	}
53	
54	method Determinant(X: array2<int>, M: int) returns (z: int)
55	  requires 1 <= M;
56	  requires X != null && M == X.Length0 && M == X.Length1;
57	  modifies X;
58	{
59	  var y := X[1-1,1-1];
60	  var a := 1;
61	  while (a != M)
62	    invariant 1 <= a <= M;
63	  {
64	    var b := a + 1;
65	    while (b != M+1)
66	      invariant a+1 <= b <= M+1;
67	    {
68	      var c := M;
69	      while (c != a)
70	      {
71	        assume X[a-1,a-1] != 0;
72	        X[b-1, c-1] := X[b-1,c-1] - X[b-1,a-1] / X[a-1,a-1] * X[a-1,c-1];
73	        c := c - 1;
74	      }
75	      b := b + 1;
76	    }
77	    a := a + 1;
78	    y := y * X[a-1,a-1];
79	  }
80	  z := y;
81	}
82

